using MiniCompiler.IR; using SemanticContracts; using SemanticQueries.Core; namespace Packages.LoopRange; public sealed class LoopRangeProvider(CompilationUnit unit):IQueryProvider<RangeKey,AbstractRange>{ public QueryResult<AbstractRange> TryGet(RangeKey key,QueryContext context){var loop=unit.Loops.FirstOrDefault(l=>l.Index==key.Value&&l.BodyPoint==key.Point);return loop is null?QueryResult<AbstractRange>.Unknown:QueryResult<AbstractRange>.Known(new(loop.StartInclusive,loop.EndExclusive-1));} }